```java
import java.io.IOException;
import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class ThumbnailCache {

    // A concurrent hash map to store the thumbnail images
    private static final ConcurrentHashMap<String, byte[]> cache = new ConcurrentHashMap<>();

    /**
     * Caches the received thumbnail image.
     * @param fileInfo the information about the file
     * @param inputStream the input stream containing the thumbnail image data
     * @throws IOException if an I/O error occurs
     */
    public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
        if (fileInfo == null || inputStream == null) {
            return;
        }

        try {
            // Generate the hash for the input stream
            String hash = generateHash(inputStream);

            // Check if the image is already in the cache
            if (cache.containsKey(hash)) {
                System.out.println("Duplicate image detected. Image not cached.");
                return;
            }

            // Read the input stream into a byte array
            byte[] imageData = inputStream.readAllBytes();

            // Cache the image data
            cache.put(hash, imageData);
            System.out.println("Image cached successfully.");

        } catch (IOException e) {
            System.err.println("I/O error occurred while caching the thumbnail image: " + e.getMessage());
            throw e;
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Hashing algorithm not found: " + e.getMessage());
        }
    }

    /**
     * Generates a hash for the given input stream.
     * @param inputStream the input stream to hash
     * @return the hash as a hex string
     * @throws IOException if an I/O error occurs
     * @throws NoSuchAlgorithmException if the hashing algorithm is not found
     */
    private static String generateHash(InputStream inputStream) throws IOException, NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[8192];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            digest.update(buffer, 0, bytesRead);
        }
        byte[] hashBytes = digest.digest();
        return bytesToHex(hashBytes);
    }

    /**
     * Converts a byte array to a hex string.
     * @param bytes the byte array to convert
     * @return the hex string representation of the byte array
     */
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
